<script setup lang="ts">
import {MapPin,Mountain,Search,ArrowLeft,ArrowRight,Compass,Landmark} from 'lucide-vue-next'
import {armeniaRegions,armeniaAreaSource,armeniaRegionStories} from '~/data/geography/armeniaRegions'
import map from '~/data/geography/armenia-map.json'
import villageCounts from '~/data/geography/armenia-village-counts.json'
import {useArmeniaVillages} from '~/composables/useArmeniaVillages'
const infoTab=ref<'overview'|'nature'|'heritage'>('overview')
const selected=ref('AM-GR'),hovered=ref<string>(),uid=useId().replace(/[^a-z0-9-]/gi,'')
const showVillageNames=ref(false)
const previousRegion=ref('AM-GR')
const {query:villageQuery,filtered:filteredVillages,visibleVillages,loading:villagesLoading,error:villagesError,updated:villagesUpdated,limit:villageLimit}=useArmeniaVillages(selected,showVillageNames)
const regionVillageCount=computed(()=>(villageCounts as Record<string,number>)[selected.value]||0)
const current=computed(()=>armeniaRegions.find(region=>region.id===selected.value)!)
const story=computed(()=>armeniaRegionStories[selected.value]!)
const infoText=computed(()=>infoTab.value==='overview'?current.value.description:story.value[infoTab.value])
const index=computed(()=>armeniaRegions.findIndex(region=>region.id===selected.value))
const shapes=map.features.map(shape=>({...shape,region:armeniaRegions.find(region=>region.id===shape.id)!}))
const hoveredName=computed(()=>armeniaRegions.find(region=>region.id===hovered.value)?.name)
const marker=computed(()=>{const [lon,lat]=current.value.coordinates,p=map.projection;return{x:(lon-p.xmin)*p.xscale*p.scale+p.offsetX,y:(p.ymax-lat)*p.scale+p.offsetY}})
watch(selected,(_id,previous)=>{if(current.value.kind==='capital')previousRegion.value=previous})
function returnToArmenia(){choose(previousRegion.value)}
function choose(id:string){showVillageNames.value=false;selected.value=id;hovered.value=undefined;infoTab.value='overview'}
function next(direction:number){choose(armeniaRegions[(index.value+direction+armeniaRegions.length)%armeniaRegions.length]!.id)}

</script>
<template>
 <section id="armenia-regions" class="armenia-explorer" aria-labelledby="armenia-title" :style="{'--region-color':current.color}">
  <header class="armenia-heading"><div><p class="armenia-eyebrow"><span class="armenia-flag" aria-hidden="true"/>FACTUM · ՄԵՐ ՀԱՅԱՍՏԱՆԸ</p><h2 id="armenia-title">Մի երկիր, <em>բազում աշխարհներ</em></h2><p>Բացահայտիր Հայաստանի մարզերը՝ քարտեզի վրա մեկ հպումով։</p></div><div class="armenia-summary"><span><strong>10</strong>մարզ</span><i/><span><strong>1</strong>մայրաքաղաք</span></div></header>
  <div class="armenia-stage">
   <div class="armenia-map-panel"><div class="map-panel-label"><span><Compass :size="15"/>ՀԱՅԱՍՏԱՆԻ ՔԱՐՏԵԶԸ</span><button v-if="current.kind==='capital'" type="button" class="map-return-button" @click="returnToArmenia"><ArrowLeft :size="14"/>Հետ՝ Հայաստանի քարտեզին</button></div>
    <LazyGlobeYerevanDistricts v-if="current.kind==='capital'"/>
    <details v-if="current.kind==='region'" :key="selected" class="village-names" @toggle="showVillageNames=($event.target as HTMLDetailsElement).open">
     <summary><span>{{regionVillageCount}} գյուղական բնակավայր</span><small>Գյուղերի անունները</small></summary>
     <div class="village-names-body">
      <label class="village-name-search"><Search :size="15"/><input v-model="villageQuery" type="search" aria-label="Որոնել գյուղերի անունները" placeholder="Գտիր գյուղի անունը…"/></label>
      <p v-if="villagesLoading" role="status">Բեռնվում է ցանկը…</p><p v-else-if="villagesError" role="alert">{{villagesError}}</p>
      <template v-else><p v-if="villageQuery.trim()" role="status">Գտնվել է՝ {{filteredVillages.length}}</p><ul aria-label="Գյուղերի անունները"><li v-for="village in visibleVillages" :key="village.id">{{village.name}}</li></ul><p v-if="!filteredVillages.length">Այս անունով գյուղ չի գտնվել։</p><button v-if="visibleVillages.length<filteredVillages.length" type="button" @click="villageLimit+=20">Ցույց տալ ավելին</button></template>
     </div>
    </details>
    <div v-if="current.kind==='region'" class="map-canvas">
    <svg class="armenia-map" :viewBox="map.viewBox" role="group" aria-label="Հայաստանի մարզերի ինտերակտիվ քարտեզ">
     <defs><pattern :id="uid+'-grid'" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M35 0H0V35" fill="none" stroke="#a7b9c0" stroke-opacity=".07" stroke-width=".6"/></pattern><radialGradient :id="uid+'-halo'"><stop stop-color="#b8a46d" stop-opacity=".13"/><stop offset="1" stop-color="#b8a46d" stop-opacity="0"/></radialGradient><filter :id="uid+'-shadow'" x="-30%" y="-30%" width="160%" height="170%"><feDropShadow dx="0" dy="12" stdDeviation="12" flood-color="#000" flood-opacity=".45"/></filter></defs>
     <rect width="600" height="560" :fill="`url(#${uid}-grid)`"/><ellipse cx="280" cy="280" rx="275" ry="265" :fill="`url(#${uid}-halo)`"/>
     <g :filter="`url(#${uid}-shadow)`"><path v-for="shape in shapes" :key="shape.id" :d="shape.path" role="button" tabindex="0" :aria-label="shape.region.name+(shape.region.kind==='region'?'ի մարզ':'՝ մայրաքաղաք')" :aria-pressed="selected===shape.id" :fill="selected===shape.id?shape.region.color:hovered===shape.id?'#415464':'#263c4b'" :stroke="selected===shape.id?'#f2d5a0':'#829caa'" :stroke-width="selected===shape.id?1.8:.8" class="region-shape" fill-rule="evenodd" @click="choose(shape.id)" @keydown.enter.prevent="choose(shape.id)" @keydown.space.prevent="choose(shape.id)" @mouseenter="hovered=shape.id" @mouseleave="hovered=undefined" @focus="hovered=shape.id" @blur="hovered=undefined"><title>{{shape.region.name}}</title></path></g>
     <path :d="map.lake.path" class="sevan-lake" fill="#3895be" stroke="#8cd8f0" stroke-width="1" fill-rule="evenodd" pointer-events="none"><title>Սևանա լիճ</title></path><text :x="map.lake.label[0]" :y="map.lake.label[1]" class="sevan-label" :transform="`rotate(40 ${map.lake.label[0]} ${map.lake.label[1]})`" text-anchor="middle" fill="#d1f1ff" font-size="9" pointer-events="none">ՍԵՎԱՆ</text>
     <g class="capital-marker" aria-hidden="true" pointer-events="none"><circle :cx="marker.x" :cy="marker.y" r="9" fill="#f2d5a022"/><circle :cx="marker.x" :cy="marker.y" r="3.5" fill="#f9e5bb" stroke="#152637" stroke-width="1.7"/><path :d="`M${marker.x+(current.id==='AM-GR'?-9:9)} ${marker.y}h${current.id==='AM-GR'?-14:14}`" stroke="#f2d5a0" stroke-width=".8"/><text :x="marker.x+(current.id==='AM-GR'?-28:28)" :text-anchor="current.id==='AM-GR'?'end':'start'" :y="marker.y+4" fill="#f3e7d3" font-size="12" font-weight="500" paint-order="stroke" stroke="#102234" stroke-width="4">{{current.center}}</text></g>
     <g transform="translate(540 38)" role="img" aria-label="Հյուսիս"><title>Հյուսիս</title><text x="0" y="-5" text-anchor="middle" fill="#bda575" font-size="10">Հ</text><path d="M0 2l-5 18 5-4 5 4Z" fill="#bda575"/><path d="M0 30V17" stroke="#bda575" stroke-opacity=".5"/></g>
    </svg>
    </div>
    <div v-if="current.kind==='region'" class="map-panel-bottom"><span><i/>{{hoveredName||current.name}}</span><span>10 մարզ · Երևան</span></div>
   </div>
   <article class="region-detail" aria-live="polite" aria-atomic="true"><div class="region-detail-top"><span>{{current.kind==='capital'?'ՀԱՅԱՍՏԱՆԻ ՄԱՅՐԱՔԱՂԱՔԸ':'ՀԱՅԱՍՏԱՆԻ ՄԱՐԶԵՐԸ'}}</span><span>{{String(index+1).padStart(2,'0')}} / 11</span></div><Transition name="region-content" mode="out-in"><div :key="current.id" class="region-content"><p class="region-subtitle">{{current.tagline}}</p><h3>{{current.name}}</h3><div class="region-facts"><div><MapPin :size="16"/><span>{{current.kind==='capital'?'Կարգավիճակ':'Մարզկենտրոն'}}<strong>{{current.kind==='capital'?'Մայրաքաղաք':current.center}}</strong></span></div><div><Compass :size="16"/><span>Տարածք<strong>{{current.area.toLocaleString('hy-AM')}} <small>կմ²</small></strong></span></div></div><nav class="region-info-tabs" aria-label="Մարզի տեղեկությունների բաժիններ"><button type="button" :aria-pressed="infoTab==='overview'" @click="infoTab='overview'">Ակնարկ</button><button type="button" :aria-pressed="infoTab==='nature'" @click="infoTab='nature'">Բնություն</button><button type="button" :aria-pressed="infoTab==='heritage'" @click="infoTab='heritage'">Պատմություն և մշակույթ</button></nav><p class="region-description">{{infoText}}</p><div class="region-landscape"><Mountain :size="17"/><span>{{current.landscape}}</span></div><div class="region-highlights"><h4><Landmark :size="15"/>Ճանաչելու վայրեր</h4><ol><li v-for="(place,i) in current.highlights" :key="place"><span>0{{i+1}}</span><div><strong>{{place}}</strong><p>{{story.places[i]}}</p></div></li></ol></div><div class="region-source-links"><a :href="current.source" target="_blank" rel="noopener noreferrer">Պաշտոնական տեղեկություն ↗</a><a :href="current.travelSource" target="_blank" rel="noopener noreferrer">Բացահայտիր ավելին ↗</a></div></div></Transition><nav class="region-paging" aria-label="Թերթել մարզերը"><button type="button" aria-label="Նախորդ մարզը" @click="next(-1)"><ArrowLeft :size="16"/>Նախորդ</button><span>{{current.kind==='capital'?'Երևան՝ առանձին կարգավիճակով':